WITH cleaned AS (SELECT id, order_id, method, amount, paid_at, status, DATE_FORMAT(paid_at, 'yyyy-MM-dd') AS paid_at_label, COALESCE(method, 'unassigned') AS method_filled FROM payments WHERE method IN ('promptpay', 'cash', 'card') AND order_id IS NOT NULL), flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM cleaned), sessions_payments AS (SELECT id, method, paid_at, status, paid_at_label, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged), metrics AS (SELECT id, method, paid_at, status, paid_at_label, session_no, ROW_NUMBER() OVER (PARTITION BY status ORDER BY paid_at, id) AS seq_no, SUM(session_no) OVER (PARTITION BY method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS session_no_sum_30d, RANK() OVER (PARTITION BY status ORDER BY session_no) AS session_no_rank FROM sessions_payments), ranked AS (SELECT id, method, status, paid_at_label, seq_no, session_no_sum_30d FROM metrics QUALIFY ROW_NUMBER() OVER (PARTITION BY method ORDER BY seq_no DESC NULLS LAST, id) = 1), metrics_payments AS (SELECT id, method, seq_no, session_no_sum_30d, AVG(session_no_sum_30d) OVER (PARTITION BY method, status) AS method_avg_session_no_sum_30d, LAST_VALUE(method, TRUE) OVER (ORDER BY session_no_sum_30d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_method FROM ranked WHERE seq_no > 5), kept_keys AS (SELECT method, id FROM metrics_payments INTERSECT SELECT method, id FROM payments WHERE amount IS NOT NULL), kept_rows AS (SELECT s.* FROM metrics_payments s INNER JOIN kept_keys k ON s.method = k.method AND s.id = k.id), base AS (SELECT id, method, session_no_sum_30d, method_avg_session_no_sum_30d, last_known_method, UPPER(method) AS method_upper FROM kept_rows WHERE method IS NOT NULL AND method IS NOT DISTINCT FROM 'cash'), stats AS (SELECT CASE WHEN session_no_sum_30d >= 31 THEN 'HIGH' ELSE 'LOW' END AS session_no_sum_30d_tier, method, AVG(method_avg_session_no_sum_30d) FILTER (WHERE method = 'cash') AS cash_avg_method_avg_session_no_sum_30d, SUM(CASE WHEN method = 'paypal' THEN session_no_sum_30d ELSE 0 END) AS paypal_session_no_sum_30d, COUNT_IF(method = 'cash') AS cash_events, SIZE(COLLECT_SET(method)) AS num_methods, ROUND(AVG(session_no_sum_30d), 2) AS avg_session_no_sum_30d, SIZE(COLLECT_SET(method)) AS num_methods_2 FROM base GROUP BY GROUPING SETS ((CASE WHEN session_no_sum_30d >= 31 THEN 'HIGH' ELSE 'LOW' END, method), (CASE WHEN session_no_sum_30d >= 31 THEN 'HIGH' ELSE 'LOW' END)) HAVING COUNT_IF(method = 'cash') > 1) SELECT session_no_sum_30d_tier, paypal_session_no_sum_30d, cash_events, avg_session_no_sum_30d, num_methods_2 FROM stats;
